{"content": "{
  "act_one": {
    "description": "建立日常与预言规则：女主收到第一封信，邮戳日期是三年后。她开始调查，同时注意到新搬来的邻居陆沉。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "第一封信",
        "core_event": "沈念在公寓邮箱里发现一封没有寄件人的信，信纸上只有一句话：'不要爱上那个男人'，邮戳日期是三年后的某一天。",
        "emotional_tone": "困惑、不解、一丝不安",
        "key_scenes": ["清晨取信", "阅读预言", "看向隔壁新搬来的邻居"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "倒计时开始",
        "core_event": "第二天又收到一封，邮戳日期变成两年后。第三天是半年后。沈念开始怀疑这是一场精心策划的恶作剧，还是真正的预言。",
        "emotional_tone": "紧张、恐惧、试图理性分析",
        "key_scenes": ["连续收到信", "邮戳日期的逼近", "试探性地观察陆沉"]
      }
    ],
    "turning_point": "沈念决定主动接近陆沉——为了验证这荒诞预言的真假，她要看看这个人究竟有什么值得被警告的。"
  },
  "act_two": {
    "description": "接近与沉溺：沈念以各种借口接近陆沉，却在相处中发现他温柔、包容、神秘。她越是想完成"调查"，就越被他吸引。邮戳日期越来越近——明天、今天。",
    "key_chapters": [
      {
        "chapter_number": 3,
        "chapter_title": "靠近陌生人",
        "core_event": "沈念开始故意制造与陆沉的偶遇，去他的咖啡店，点最苦的咖啡，观察他的一举一动。她试图找出"那个男人"危险在哪里。",
        "emotional_tone": "警惕、好奇、一丝愧疚",
        "key_scenes": ["咖啡店搭话", "邻居门口的交谈", "陆沉的温柔日常"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "沉溺",
        "core_event": "沈念发现自己不可救药地爱上了陆沉。每一次靠近都像在饮鸩止渴。她试图停止，但邮戳日期已经逼近——明天。",
        "emotional_tone": "痛苦、挣扎、甜蜜与绝望交织",
        "key_scenes": ["雨天的咖啡店", "陆沉的倾听", "沈念的自我厌恶"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "今天",
        "core_event": "邮戳日期变成今天的那封信送达。沈念终于读懂——这不是警告，而是已经发生的事在等待发生。她意识到，她就是写那封信的人，在杀死他之后。",
        "emotional_tone": "恐惧、顿悟、绝望的接纳",
        "key_scenes": ["今天的信", "回忆过往的细节", "发现自己就是预言本身"]
      }
    ],
    "turning_point": "沈念终于明白：她不是被警告不要爱上他，而是被警告——她将杀死他。这份爱越深，动手的时刻越不可逃避。"
  },
  "act_three": {
    "description": "执行与结局：沈念面临最后的抉择——杀死陆沉，或者让他离开。在时间的规则怪谈中，她做出了最终的选择。",
    "key_chapters": [
      {
        "chapter_number": 6,
        "chapter_title": "最后一封信",
        "core_event": "沈念用颤抖的手写下最后一句话——'不要爱上那个男人'。她把它放进邮箱，看着邮戳日期归零。然后，她走向陆沉。",
        "emotional_tone": "平静的疯狂、决绝的爱",
        "key_scenes": ["写预言信", "把信投入邮箱", "走向陆沉"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "成为过去",
        "core_event": "开放式结局。沈念的刀举起/放下，陆沉微笑/惊讶。时间的循环完成，或者打破。信上的字迹干涸，邮戳永远停在这一天。",
        "emotional_tone": "宿命感的余韵",
        "key_scenes": ["关键抉择", "时间循环的闭合/打破", "最后一个画面"]
      }
    ],
    "turning_point": "她的选择就是她的命运——无论杀或不杀，她都已经成为了那个写下预言的人。"
  }
}
", "path": "outline.json"}

